package com.lianxibu.site.service.content;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.service.identity.IdentityService;
import com.lianxibu.site.service.jobs.*;
import java.time.*;
import org.junit.jupiter.api.Test;
import org.springframework.transaction.PlatformTransactionManager;

/** Exact frozen content facade routing into real command ports; no repository or model transport. */
class OwnerReportRoutingTest {
 final IdentityService.Actor actor=new IdentityService.Actor("fictional-owner","owner");
 ContentService.GenerationIntentWrite request(String mode){return new ContentService.GenerationIntentWrite("daily",Instant.parse("2025-12-31T16:00:00Z"),Instant.parse("2026-01-01T16:00:00Z"),"Asia/Shanghai",mode,mode.equals("initial")?null:0L,"Fictional owner report");}
 PublishedContentFacade facade(PublishedContentFacade.OwnerOperations owner,OwnerReportOperations reports){return new PublishedContentFacade(mock(ContentReadService.class),mock(PublishedContentFacade.Projection.class),mock(PlatformTransactionManager.class),owner,reports);}
 @Test void InitialAndSupplementKeepEveryFrozenArgumentAndOriginalResponse(){var initial=mock(OwnerReportInitialService.class);var supplement=mock(OwnerReportSupplementService.class);var routing=new OwnerReportOperations(initial,supplement);var facade=facade(null,routing);var first=mock(ContentService.Job.class);var second=mock(ContentService.Job.class);var a=request("initial");var b=request("supplement");when(initial.generationIntent(actor,a,"fictional-initial","fictional-csrf","https://fictional.invalid")).thenReturn(first);when(supplement.generationIntent(actor,b,"fictional-supplement","fictional-csrf","https://fictional.invalid")).thenReturn(second);assertSame(first,facade.generationIntent(actor,a,"fictional-initial","fictional-csrf","https://fictional.invalid"));assertSame(second,facade.generationIntent(actor,b,"fictional-supplement","fictional-csrf","https://fictional.invalid"));verify(initial).generationIntent(actor,a,"fictional-initial","fictional-csrf","https://fictional.invalid");verify(supplement).generationIntent(actor,b,"fictional-supplement","fictional-csrf","https://fictional.invalid");verifyNoMoreInteractions(initial,supplement);}
 @Test void SupplementActionDoesNotEnterPublicationCommandsAndPublicationStillUsesItsOriginalService(){var initial=mock(OwnerReportInitialService.class);var supplement=mock(OwnerReportSupplementService.class);var commands=mock(OwnerContentCommands.class);var owner=new PublishedContentFacade.OwnerOperations(mock(OwnerContentReadService.class),commands,mock(OwnerContentEditService.class),mock(OwnerContentValidityService.class),mock(PublishedContentFacade.Versions.class));var facade=facade(owner,new OwnerReportOperations(initial,supplement));var regenerate=new ContentService.ContentAction(4,"supplement_generate","Fictional changed inputs",null);var publish=new ContentService.ContentAction(4,"publish","Fictional reviewed publication",null);var prepared=mock(ContentService.ActionResult.class);var published=mock(ContentService.ActionResult.class);when(supplement.action(actor,"report","fictional-content",regenerate,"fictional-regenerate","fictional-csrf","https://fictional.invalid")).thenReturn(prepared);when(commands.action(actor,"report","fictional-content",publish,"fictional-publish","fictional-csrf","https://fictional.invalid")).thenReturn(published);assertSame(prepared,facade.action(actor,"report","fictional-content",regenerate,"fictional-regenerate","fictional-csrf","https://fictional.invalid"));assertSame(published,facade.action(actor,"report","fictional-content",publish,"fictional-publish","fictional-csrf","https://fictional.invalid"));verify(commands).action(actor,"report","fictional-content",publish,"fictional-publish","fictional-csrf","https://fictional.invalid");verifyNoMoreInteractions(commands);verifyNoInteractions(initial);}
 @Test void UnconfiguredRoutesFailClosedAndColdAdapterCreatesNoDependencyTraffic(){var initial=mock(OwnerReportInitialService.class);var supplement=mock(OwnerReportSupplementService.class);new OwnerReportOperations(initial,supplement);verifyNoInteractions(initial,supplement);var facade=facade(null,null);assertEquals(IdentityService.Refusal.TEMPORARILY_UNAVAILABLE,assertThrows(IdentityService.Rejected.class,()->facade.generationIntent(actor,request("initial"),"fictional-key","fictional-csrf","https://fictional.invalid")).refusal());assertThrows(IdentityService.Rejected.class,()->facade.action(actor,"report","fictional-content",new ContentService.ContentAction(1,"supplement_generate","Fictional reason",null),"fictional-key","fictional-csrf","https://fictional.invalid"));}
}
